43	template <bool like, bool no_capture, bool case_insensitive>
44	inline Regexp createRegexp(const std::string & pattern)
45	{
46	    int flags = OptimizedRegularExpression::RE_DOT_NL;
47	    if constexpr (no_capture)
48	        flags |= OptimizedRegularExpression::RE_NO_CAPTURE;
49	    if constexpr (case_insensitive)
50	        flags |= OptimizedRegularExpression::RE_CASELESS;
51	
52	    if constexpr (like)
53	        return {likePatternToRegexp(pattern), flags};
54	    else
55	        return {pattern, flags};
