169	template <bool save_indices, bool WithEditDistance>
170	inline Regexps constructRegexps(const std::vector<String> & str_patterns, [[maybe_unused]] std::optional<UInt32> edit_distance)
171	{
172	    /// Common pointers
173	    std::vector<const char *> patterns;
174	    std::vector<unsigned int> flags;
175	
176	    /// Pointer for external edit distance compilation
177	    std::vector<hs_expr_ext> ext_exprs;
178	    std::vector<const hs_expr_ext *> ext_exprs_ptrs;
179	
180	    patterns.reserve(str_patterns.size());
181	    flags.reserve(str_patterns.size());
182	
183	    if constexpr (WithEditDistance)
184	    {
185	        ext_exprs.reserve(str_patterns.size());
186	        ext_exprs_ptrs.reserve(str_patterns.size());
187	    }
188	
189	    for (const StringRef ref : str_patterns)
190	    {
191	        patterns.push_back(ref.data);
192	        /* Flags below are the pattern matching flags.
193	         * HS_FLAG_DOTALL is a compile flag where matching a . will not exclude newlines. This is a good
194	         * performance practice according to Hyperscan API. https://intel.github.io/hyperscan/dev-reference/performance.html#dot-all-mode
195	         * HS_FLAG_ALLOWEMPTY is a compile flag where empty strings are allowed to match.
196	         * HS_FLAG_UTF8 is a flag where UTF8 literals are matched.
197	         * HS_FLAG_SINGLEMATCH is a compile flag where each pattern match will be returned only once. it is a good performance practice
198	         * as it is said in the Hyperscan documentation. https://intel.github.io/hyperscan/dev-reference/performance.html#single-match-flag
199	         */
200	        flags.push_back(HS_FLAG_DOTALL | HS_FLAG_SINGLEMATCH | HS_FLAG_ALLOWEMPTY | HS_FLAG_UTF8);
201	        if constexpr (WithEditDistance)
202	        {
203	            /// Hyperscan currently does not support UTF8 matching with edit distance.
204	            flags.back() &= ~HS_FLAG_UTF8;
205	            ext_exprs.emplace_back();
206	            /// HS_EXT_FLAG_EDIT_DISTANCE is a compile flag responsible for Levenstein distance.
207	            ext_exprs.back().flags = HS_EXT_FLAG_EDIT_DISTANCE;
208	            ext_exprs.back().edit_distance = edit_distance.value();
209	            ext_exprs_ptrs.push_back(&ext_exprs.back());
210	        }
211	    }
212	    hs_database_t * db = nullptr;
213	    hs_compile_error_t * compile_error;
214	
215	    std::unique_ptr<unsigned int[]> ids;
216	
217	    /// We mark the patterns to provide the callback results.
218	    if constexpr (save_indices)
219	    {
220	        ids.reset(new unsigned int[patterns.size()]);
221	        for (size_t i = 0; i < patterns.size(); ++i)
222	            ids[i] = i + 1;
223	    }
224	
225	    hs_error_t err;
226	    if constexpr (!WithEditDistance)
227	        err = hs_compile_multi(
228	            patterns.data(),
229	            flags.data(),
230	            ids.get(),
231	            patterns.size(),
232	            HS_MODE_BLOCK,
233	            nullptr,
234	            &db,
235	            &compile_error);
236	    else
237	        err = hs_compile_ext_multi(
238	            patterns.data(),
239	            flags.data(),
240	            ids.get(),
241	            ext_exprs_ptrs.data(),
242	            patterns.size(),
243	            HS_MODE_BLOCK,
244	            nullptr,
245	            &db,
246	            &compile_error);
247	
248	    if (err != HS_SUCCESS)
249	    {
250	        /// CompilerError is a unique_ptr, so correct memory free after the exception is thrown.
251	        CompilerError error(compile_error);
252	
253	        if (error->expression < 0)
254	            throw Exception(String(error->message), ErrorCodes::LOGICAL_ERROR);
255	        else
256	            throw Exception(
257	                "Pattern '" + str_patterns[error->expression] + "' failed with error '" + String(error->message),
258	                ErrorCodes::BAD_ARGUMENTS);
259	    }
260	
261	    ProfileEvents::increment(ProfileEvents::RegexpCreated);
262	
263	    /// We allocate the scratch space only once, then copy it across multiple threads with hs_clone_scratch
264	    /// function which is faster than allocating scratch space each time in each thread.
265	    hs_scratch_t * scratch = nullptr;
266	    err = hs_alloc_scratch(db, &scratch);
267	
268	    /// If not HS_SUCCESS, it is guaranteed that the memory would not be allocated for scratch.
269	    if (err != HS_SUCCESS)
270	        throw Exception("Could not allocate scratch space for hyperscan", ErrorCodes::CANNOT_ALLOCATE_MEMORY);
271	
272	    return {db, scratch};
273	}
