275	/// If WithEditDistance is False, edit_distance must be nullopt
276	/// Also, we use templates here because each instantiation of function
277	/// template has its own copy of local static variables which must not be the same
278	/// for different hyperscan compilations.
279	template <bool save_indices, bool WithEditDistance>
280	inline Regexps * get(const std::vector<std::string_view> & patterns, std::optional<UInt32> edit_distance)
281	{
282	    static Pool known_regexps; /// Different variables for different pattern parameters, thread-safe in C++11
283	
284	    std::vector<String> str_patterns;
285	    str_patterns.reserve(patterns.size());
286	    for (const auto & pattern : patterns)
287	        str_patterns.emplace_back(std::string(pattern.data(), pattern.size()));
288	
289	    /// Get the lock for finding database.
290	    std::unique_lock lock(known_regexps.mutex);
291	
292	    auto it = known_regexps.storage.find({str_patterns, edit_distance});
293	
294	    /// If not found, compile and let other threads wait.
295	    if (known_regexps.storage.end() == it)
296	    {
297	        it = known_regexps.storage
298	                 .emplace(std::piecewise_construct, std::make_tuple(std::move(str_patterns), edit_distance), std::make_tuple())
299	                 .first;
300	        it->second.setConstructor([&str_patterns = it->first.first, edit_distance]()
301	        {
302	            return constructRegexps<save_indices, WithEditDistance>(str_patterns, edit_distance);
303	        });
304	    }
305	
306	    /// Unlock before possible construction.
307	    lock.unlock();
308	    return it->second();
309	}
310	
311	}
