27	/// Thread-safe cache that evicts entries which are not used for a long time.
28	/// WeightFunction is a functor that takes Mapped as a parameter and returns "weight" (approximate size)
29	/// of that value.
30	/// Cache starts to evict entries when their total weight exceeds max_size.
31	/// Value weight should not change after insertion.
32	template <typename TKey, typename TMapped, typename HashFunction = std::hash<TKey>, typename WeightFunction = TrivialWeightFunction<TMapped>>
33	class LRUCache
34	{
35	public:
36	    using Key = TKey;
37	    using Mapped = TMapped;
38	    using MappedPtr = std::shared_ptr<Mapped>;
39	
40	    /** Initialize LRUCache with max_size and max_elements_size.
41	      * max_elements_size == 0 means no elements size restrictions.
42	      */
43	    explicit LRUCache(size_t max_size_, size_t max_elements_size_ = 0)
44	        : max_size(std::max(static_cast<size_t>(1), max_size_))
45	        , max_elements_size(max_elements_size_)
46	        {}
47	
48	    MappedPtr get(const Key & key)
49	    {
50	        std::lock_guard lock(mutex);
51	
52	        auto res = getImpl(key);
53	        if (res)
54	            ++hits;
55	        else
56	            ++misses;
57	
58	        return res;
59	    }
60	
61	    void set(const Key & key, const MappedPtr & mapped)
62	    {
63	        std::lock_guard lock(mutex);
64	
65	        setImpl(key, mapped);
66	    }
67	
68	    void remove(const Key & key)
69	    {
70	        std::lock_guard lock(mutex);
71	        auto it = cells.find(key);
72	        if (it == cells.end())
73	            return;
74	        auto & cell = it->second;
75	        current_size -= cell.size;
76	        queue.erase(cell.queue_iterator);
77	        cells.erase(it);
78	    }
79	
80	    /// If the value for the key is in the cache, returns it. If it is not, calls load_func() to
81	    /// produce it, saves the result in the cache and returns it.
82	    /// Only one of several concurrent threads calling getOrSet() will call load_func(),
83	    /// others will wait for that call to complete and will use its result (this helps prevent cache stampede).
84	    /// Exceptions occurring in load_func will be propagated to the caller. Another thread from the
85	    /// set of concurrent threads will then try to call its load_func etc.
86	    ///
87	    /// Returns std::pair of the cached value and a bool indicating whether the value was produced during this call.
88	    template <typename LoadFunc>
89	    std::pair<MappedPtr, bool> getOrSet(const Key & key, LoadFunc && load_func)
90	    {
91	        InsertTokenHolder token_holder;
92	        {
93	            std::lock_guard cache_lock(mutex);
94	
95	            auto val = getImpl(key);
96	            if (val)
97	            {
98	                ++hits;
99	                return std::make_pair(val, false);
100	            }
101	
102	            auto & token = insert_tokens[key];
103	            if (!token)
104	                token = std::make_shared<InsertToken>(*this);
105	
106	            token_holder.acquire(&key, token, cache_lock);
107	        }
108	
109	        InsertToken * token = token_holder.token.get();
110	
111	        std::lock_guard token_lock(token->mutex);
112	
113	        token_holder.cleaned_up = token->cleaned_up;
114	
115	        if (token->value)
116	        {
117	            /// Another thread already produced the value while we waited for token->mutex.
118	            ++hits;
119	            return std::make_pair(token->value, false);
120	        }
121	
122	        ++misses;
123	        token->value = load_func();
124	
125	        std::lock_guard cache_lock(mutex);
126	
127	        /// Insert the new value only if the token is still in present in insert_tokens.
128	        /// (The token may be absent because of a concurrent reset() call).
129	        bool result = false;
130	        auto token_it = insert_tokens.find(key);
131	        if (token_it != insert_tokens.end() && token_it->second.get() == token)
132	        {
133	            setImpl(key, token->value);
134	            result = true;
135	        }
136	
137	        if (!token->cleaned_up)
138	            token_holder.cleanup(token_lock, cache_lock);
139	
140	        return std::make_pair(token->value, result);
141	    }
142	
143	    void getStats(size_t & out_hits, size_t & out_misses) const
144	    {
145	        std::lock_guard lock(mutex);
146	        out_hits = hits;
147	        out_misses = misses;
148	    }
149	
150	    size_t weight() const
151	    {
152	        std::lock_guard lock(mutex);
153	        return current_size;
154	    }
155	
156	    size_t count() const
157	    {
158	        std::lock_guard lock(mutex);
159	        return cells.size();
160	    }
161	
162	    size_t maxSize() const
163	    {
164	        return max_size;
165	    }
166	
167	    void reset()
168	    {
169	        std::lock_guard lock(mutex);
170	        queue.clear();
171	        cells.clear();
172	        insert_tokens.clear();
173	        current_size = 0;
174	        hits = 0;
175	        misses = 0;
176	    }
177	
178	    virtual ~LRUCache() = default;
179	
180	protected:
181	    using LRUQueue = std::list<Key>;
182	    using LRUQueueIterator = typename LRUQueue::iterator;
183	
184	    struct Cell
185	    {
186	        MappedPtr value;
187	        size_t size;
188	        LRUQueueIterator queue_iterator;
189	    };
190	
191	    using Cells = std::unordered_map<Key, Cell, HashFunction>;
192	
193	    Cells cells TSA_GUARDED_BY(mutex);
194	
195	    mutable std::mutex mutex;
196	private:
197	
198	    /// Represents pending insertion attempt.
199	    struct InsertToken
200	    {
201	        explicit InsertToken(LRUCache & cache_) : cache(cache_) {}
202	
203	        std::mutex mutex;
204	        bool cleaned_up TSA_GUARDED_BY(mutex) = false;
205	        MappedPtr value TSA_GUARDED_BY(mutex);
206	
207	        LRUCache & cache;
208	        size_t refcount = 0; /// Protected by the cache mutex
209	    };
210	
211	    using InsertTokenById = std::unordered_map<Key, std::shared_ptr<InsertToken>, HashFunction>;
212	
213	    /// This class is responsible for removing used insert tokens from the insert_tokens map.
214	    /// Among several concurrent threads the first successful one is responsible for removal. But if they all
215	    /// fail, then the last one is responsible.
216	    struct InsertTokenHolder
217	    {
218	        const Key * key = nullptr;
219	        std::shared_ptr<InsertToken> token;
220	        bool cleaned_up = false;
221	
222	        InsertTokenHolder() = default;
223	
224	        void acquire(const Key * key_, const std::shared_ptr<InsertToken> & token_, [[maybe_unused]] std::lock_guard<std::mutex> & cache_lock)
225	            TSA_NO_THREAD_SAFETY_ANALYSIS // disabled only because we can't reference the parent-level cache mutex from here
226	        {
227	            key = key_;
228	            token = token_;
229	            ++token->refcount;
230	        }
231	
232	        void cleanup([[maybe_unused]] std::lock_guard<std::mutex> & token_lock, [[maybe_unused]] std::lock_guard<std::mutex> & cache_lock)
233	            TSA_NO_THREAD_SAFETY_ANALYSIS // disabled only because we can't reference the parent-level cache mutex from here
234	        {
235	            token->cache.insert_tokens.erase(*key);
236	            token->cleaned_up = true;
237	            cleaned_up = true;
238	        }
239	
240	        ~InsertTokenHolder()
241	        {
242	            if (!token)
243	                return;
244	
245	            if (cleaned_up)
246	                return;
247	
248	            std::lock_guard token_lock(token->mutex);
249	
250	            if (token->cleaned_up)
251	                return;
252	
253	            std::lock_guard cache_lock(token->cache.mutex);
254	
255	            --token->refcount;
256	            if (token->refcount == 0)
257	                cleanup(token_lock, cache_lock);
258	        }
259	    };
260	
261	    friend struct InsertTokenHolder;
262	
263	
264	    InsertTokenById insert_tokens TSA_GUARDED_BY(mutex);
265	
266	    LRUQueue queue TSA_GUARDED_BY(mutex);
267	
268	    /// Total weight of values.
269	    size_t current_size TSA_GUARDED_BY(mutex) = 0;
270	    const size_t max_size;
271	    const size_t max_elements_size;
272	
273	    std::atomic<size_t> hits {0};
274	    std::atomic<size_t> misses {0};
275	
276	    const WeightFunction weight_function;
277	
278	    MappedPtr getImpl(const Key & key) TSA_REQUIRES(mutex)
279	    {
280	        auto it = cells.find(key);
281	        if (it == cells.end())
282	        {
283	            return MappedPtr();
284	        }
285	
286	        Cell & cell = it->second;
287	
288	        /// Move the key to the end of the queue. The iterator remains valid.
289	        queue.splice(queue.end(), queue, cell.queue_iterator);
290	
291	        return cell.value;
292	    }
293	
294	    void setImpl(const Key & key, const MappedPtr & mapped) TSA_REQUIRES(mutex)
295	    {
296	        auto [it, inserted] = cells.emplace(std::piecewise_construct,
297	            std::forward_as_tuple(key),
298	            std::forward_as_tuple());
299	
300	        Cell & cell = it->second;
301	
302	        if (inserted)
303	        {
304	            try
305	            {
306	                cell.queue_iterator = queue.insert(queue.end(), key);
307	            }
308	            catch (...)
309	            {
310	                cells.erase(it);
311	                throw;
312	            }
313	        }
314	        else
315	        {
316	            current_size -= cell.size;
317	            queue.splice(queue.end(), queue, cell.queue_iterator);
318	        }
319	
320	        cell.value = mapped;
321	        cell.size = cell.value ? weight_function(*cell.value) : 0;
322	        current_size += cell.size;
323	
324	        removeOverflow();
325	    }
326	
327	    void removeOverflow() TSA_REQUIRES(mutex)
328	    {
329	        size_t current_weight_lost = 0;
330	        size_t queue_size = cells.size();
331	
332	        while ((current_size > max_size || (max_elements_size != 0 && queue_size > max_elements_size)) && (queue_size > 1))
333	        {
334	            const Key & key = queue.front();
335	
336	            auto it = cells.find(key);
337	            if (it == cells.end())
338	            {
339	                LOG_ERROR(&Poco::Logger::get("LRUCache"), "LRUCache became inconsistent. There must be a bug in it.");
340	                abort();
341	            }
342	
343	            const auto & cell = it->second;
344	
345	            current_size -= cell.size;
346	            current_weight_lost += cell.size;
347	
348	            cells.erase(it);
349	            queue.pop_front();
350	            --queue_size;
351	        }
352	
353	        onRemoveOverflowWeightLoss(current_weight_lost);
354	
355	        if (current_size > (1ull << 63))
356	        {
357	            LOG_ERROR(&Poco::Logger::get("LRUCache"), "LRUCache became inconsistent. There must be a bug in it.");
358	            abort();
359	        }
360	    }
361	
362	    /// Override this method if you want to track how much weight was lost in removeOverflow method.
363	    virtual void onRemoveOverflowWeightLoss(size_t /*weight_loss*/) {}
364	};
