/// Wraps a lazily constructed Regexps object. The compilation of the patterns by vectorscan is expensive, so it is deferred until the
/// object is used for the first time. This way, the cache below does not need to hold its mutex during compilation.
class DeferredConstructedRegexps
{
public:
    explicit DeferredConstructedRegexps(std::function<Regexps()> constructor_) : constructor(std::move(constructor_)) { }

    Regexps * get()
    {
        std::lock_guard lock(mutex);
        if (!regexps)
            regexps = constructor();
        return &*regexps;
    }

private:
    std::mutex mutex;
    const std::function<Regexps()> constructor;
    std::optional<Regexps> regexps TSA_GUARDED_BY(mutex);
};

using DeferredConstructedRegexpsPtr = std::shared_ptr<DeferredConstructedRegexps>;
